import { ethers } from "ethers-v5";

/**
 * Verifies that a provided signer is valid and properly configured.
 * Checks for address accessibility and provider connection.
 * 
 * @param {ethers.Signer} signer - The ethers v5 signer to verify
 * 
 * @returns {<ethers.Signer>} The verified signer
 * @throws {Error} If signer is invalid, missing, or not properly configured:
 *   - "No signer provided" - If signer is undefined/null
 *   - "Could not get signer address" - If signer address is inaccessible
 *   - "Signer is not connected to a provider" - If signer lacks provider
 * 
 * 
 */
export const verifySigner = async (
  signer,
 
) => {
  if (!signer) {
    throw new Error(`Verify Signer: No signer provided!`);
  }

  try {
    const address = await signer.getAddress();
    
    if (!address) {
      throw new Error("Verify Signer: Could not get signer address!");
    }

    // Verify the provider connection
    const provider = signer.provider;
    if (!provider) {
      throw new Error("Verify Signer: Signer is not connected to a provider!");
    }

    return signer;
  } catch (error) {
    if (options.requestAddress) {
      // In ethers v5, if we don't have an address, we can't really request one
      // The signer needs to be connected to a provider and have an address already
      throw new Error("Verify Signer: Signer is not properly connected!");
    }
    throw error;
  }
};
