import { getConfig } from "../constants/config";
import { getTotalAmountOut } from "./getTotalAmountOut";
import { ethers } from "ethers-v5";
import { symphonyAddress, symphonyAbi } from "../../common/constants/contract";

/**
 * Calculates the minimum amount out for a swap considering slippage tolerance.
 * This function can handle various input types and formats, including routes and raw amounts.
 *
 * @param {Object} params - The parameters object
 * @param {(Array|string|ethers.BigNumber|bigint)} params.variable - The input value. Can be:
 *   - Array: A route array from getRoute
 *   - string: A number in string format (raw or formatted)
 *   - ethers.BigNumber: Amount in BigNumber format
 *   - bigint: Amount in BigInt format
 * @param {(string|number)} [params.slippageAmount=0.5] - Slippage tolerance. Defaults to config value (0.5%)
 *   - If isBps is false: percentage (e.g., "0.5" for 0.5%)
 *   - If isBps is true: basis points (e.g., "100000" for 1%)
 * @param {Object} [params.options] - Additional options
 * @param {boolean} [params.options.isRaw=true] - If true, amounts are in raw units (wei)
 * @param {boolean} [params.options.isBps=false] - If true, slippage is in basis points
 * @param {number} [params.options.outTokenDecimals=undefined] - Decimals of output token (required if isRaw=false)
 *
 * @returns {ethers.BigNumber} The minimum amount out considering slippage
 *
 * @throws {Error} If variable or slippageAmount is missing/invalid
 * @throws {Error} If slippage calculation fails
 *
 * @default
 * - slippageAmount: "0.5" (0.5% from config)
 * - options.isRaw: true
 * - options.isBps: false
 * - options.outTokenDecimals: undefined
 *
 * @example
 * // Example 1: Calculate min amount out for a route
 * const route = await getRoute({ ... });
 * const minAmountOut = calculateAmountOutMin({
 *   variable: route,
 *   slippageAmount: "0.5" // 0.5% slippage
 * });
 *
 * @example
 * // Example 2: Calculate min amount for raw amount
 * const minAmount = calculateAmountOutMin({
 *   variable: "1000000000000000000", // 1 ETH in wei
 *   slippageAmount: "50",
 *   options: {
 *     isRaw: true,
 *     isBps: true // Using basis points
 *   }
 * });
 *
 * @example
 * // Example 3: Calculate min amount for formatted amount
 * const minAmount = calculateAmountOutMin({
 *   variable: "1.0", // 1 ETH
 *   options: {
 *     isRaw: false,
 *     outTokenDecimals: 18
 *   }
 * });
 */
export const calculateAmountOutMin = async ({
  variable, // route or amount
  slippageAmount = getConfig().slippage,
  options = {
    isRaw: true,
    isBps: false,
    outTokenDecimals: undefined,
  },
}) => {
  const feeParams = getConfig().feeParams;
  const provider = getConfig().provider;
  let amountOut = ethers.BigNumber.from(0);
  let slippage = 0;
  if (
    !variable ||
    !slippageAmount ||
    (Array.isArray(variable) && variable?.length == 0)
  ) {
    throw new Error("Invalid or missing `variable` or `slippageAmount` arg.");
  }

  //If variable is Route
  if (Array.isArray(variable) && variable.length != 0)
    amountOut = getTotalAmountOut(variable).amountOut;

  //If variable is raw string
  if (typeof variable == "string" && options.isRaw)
    amountOut = ethers.BigNumber.from(variable);

  // If variable is formatted string
  if (typeof variable == "string" && !options.isRaw)
    amountOut = ethers.utils.parseUnits(variable, options.outTokenDecimals);

  // If variable is bigint
  if (typeof variable == "bigint")
    amountOut = ethers.BigNumber.from(variable.toString());
  if (ethers.BigNumber.isBigNumber(variable)) amountOut = variable;

  // if slippage is formatted string or float/number
  if (
    (typeof slippageAmount == "string" || typeof slippageAmount == "number") &&
    !options.isBps
  )
    slippage = slippageAmount.toString();
  // If slippage is bps units
  if (options.isBps) slippage = (Number(slippageAmount) / 10000).toString();

  if (Number(slippageAmount) == 0) {
    if (options.isRaw) return ethers.BigNumber.from(amountOut);
    if (!options.isRaw)
      return ethers.BigNumber.from(
        ethers.utils.formatUnits(amountOut, options.outTokenDecimals)
      );
    console.error(
      "Slippage is set to 0. Please set slippage to a non-zero value if not intended."
    );
  }

  if (
    (Number(slippageAmount) >= 100 && !options.isBps) ||
    (Number(slippageAmount) >= 1000000 && options.isBps)
  ) {
    console.error(
      "Slippage is set to 100% or higher. Please set slippage to a lower value if not intended."
    );
    return ethers.BigNumber.from(0).toString();
  }

  if (!slippage || amountOut.isZero()) {
    if (!slippage) throw new Error("Error setting slippage!");
    if (amountOut.isZero())
      throw new Error(
        "Error setting slippage: No amount out provided! This might mean swap value is too low. (Return token amount is 0)"
      );
  }
  const integerPart = slippage.split(".")[0] || "0";
  const fractionalPart = slippage.split(".")[1] || "";

  const numerator = (
    integerPart.toString() + fractionalPart.toString()
  ).replace(/^0+|0+$/g, "");

  const denominatorExp = fractionalPart.length + 2;

  const numeratorBN = ethers.BigNumber.from(numerator);
  const denominatorBN = ethers.BigNumber.from(10).pow(denominatorExp);

  let amountOutMin = amountOut.sub(
    amountOut.mul(numeratorBN).div(denominatorBN)
  );

  if (amountOutMin.isNegative()) {
    console.error(
      "Error setting slippage: Minimum amount is negative. This might mean slippage value is higher than 100%. Minimum amount set to `0`."
    );
    return ethers.BigNumber.from(0).toString();
  }

  // DEDUCT CUSTOM FEE IF THERES A CUSTOM FEE
  if (
    feeParams.feeAddress !== "0x0000000000000000000000000000000000000000" &&
    Number(feeParams.paramFee) &&
    Number(feeParams.paramFee) !== 0
  ) {
    const feeAmount = amountOutMin
      .mul(ethers.BigNumber.from(feeParams.paramFee))
      .div(ethers.BigNumber.from(1000));
    amountOutMin = amountOutMin.sub(feeAmount);
  }

  // DEDUCT PLATFORM FEE IF THERES NOT A CUSTOM FEE
  if (feeParams.feeAddress === "0x0000000000000000000000000000000000000000") {
    const contract = new ethers.Contract(
      symphonyAddress,
      symphonyAbi,
      provider
    );
    const platformFee = await contract.feePercentage();
    const feeAmount = amountOutMin
      .mul(platformFee)
      .div(ethers.BigNumber.from(1000));
    amountOutMin = amountOutMin.sub(feeAmount);
  }

  return amountOutMin;
};
